def _get_value_column(df, vcol_name):
    """Find the base value column (exact match after stripping)."""
    target = str(vcol_name).strip()
    # look for exact match
    for c in df.columns:
        # base name is c if no _N suffix; compare against c split by _ with numeric tail removed conceptually
        base = c
        # remove trailing _digits if it's a dedup marker and not part of original?
        # but we named as c_N; the base is what we want for recorded? we want the base recorded column
        # check if matches target exactly
        if c == target:
            return c
    # fallback: find column whose base (before last _N if N is digit) equals target
    for c in df.columns:
        # split
        if '_' in c:
            # check if suffix is digit
            parts = c.split('_')
            if parts[-1].isdigit():
                base = '_'.join(parts[:-1])
                if base == target:
                    return c  # return the base-named variant? for our deduping we kept base as first; duplicates got _N
    # also try just equality ignoring trailing spaces already stripped
    for c in df.columns:
        if c.strip() == target:
            return c
    # last resort: return target if exists
    if target in df.columns:
        return target
    return None
